def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    flip_table = {2: True, 3: False}  # key colour -> mirror left-right?
    objs = objects(g, bg=bg, diagonal=True, multicolour=True)
    templates = []
    for o in objs:
        if o['size'] < 2:
            continue
        cols = [int(g[y, x]) for y, x in o['cells']]
        cnt = {c: cols.count(c) for c in set(cols)}
        singles = [c for c, n in cnt.items() if n == 1]
        if len(singles) != 1 or len(cnt) < 2:
            continue
        key = singles[0]
        y0, x0, y1, x1 = o['box']
        t = np.full((y1 - y0 + 1, x1 - x0 + 1), bg)
        for y, x in o['cells']:
            t[y - y0, x - x0] = g[y, x]
        if flip_table.get(key, False):
            t = np.fliplr(t)
        templates.append((key, t))
    H, W = g.shape
    for key, t in templates:
        py, px = np.argwhere(t == key)[0]
        for o in objs:
            if o['size'] == 1 and o['colour'] == key:
                ty, tx = o['cells'][0]
                for yy, xx in np.argwhere(t != bg):
                    if t[yy, xx] == key:
                        continue
                    Y, X = ty + yy - py, tx + xx - px
                    if 0 <= Y < H and 0 <= X < W and out[Y, X] == bg:
                        out[Y, X] = t[yy, xx]
                emit(out, f"Stamp the key-{key} template body around the lone {key} at ({ty},{tx})"
                          + (" (mirrored left-right)" if flip_table.get(key, False) else ""))
    emit(out, "All lone key cells have received their template bodies")
    return out
